type Fact = { query: RegExp[]; choices: RegExp[][]; trueChoice: string; rationale: string };
const fixed = (query: RegExp[], choices: RegExp[], trueChoice: string, rationale: string): Fact =>
  ({ query, choices: query.map(() => choices), trueChoice, rationale });
const variable = (query: RegExp[], choices: RegExp[][], trueChoice: string, rationale: string): Fact =>
  ({ query, choices, trueChoice, rationale });

